<?php require 'common.php'; try{$in=body_json();$raw=$in['json']??'';if(!$raw)throw new Exception('Paste JSON or page source first.');$media=extract_media(json_from_raw($raw));if(!$media)throw new Exception('No media items found in reels_media.');foreach($media as &$x)$x['id']=bin2hex(random_bytes(8));send_json(['ok'=>true,'media'=>$media]);}catch(Throwable $e){send_json(['ok'=>false,'error'=>$e->getMessage()],400);}
